 "DWG se ukládá přímo v prohlížeči (vrstvy OBRYS/SKRYTE/OSY/KOTY, typy a tloušťky čar, verze AutoCAD 2000–2018+). DXF je ve formátu AutoCAD R12 pro starší a open-source programy (LibreCAD, QCAD).": "DWG is written directly in the browser (layers OBRYS/SKRYTE/OSY/KOTY, line types and widths, AutoCAD 2000–2018+ versions). DXF is in AutoCAD R12 format for older and open-source programs (LibreCAD, QCAD).",
