 "Kategorie": "Categories",
 "Každá hrana může mít vlastní poloměr; liší-li se začátek a konec, mění se poloměr podél hrany lineárně. Řídicí body uprostřed hrany jádro neumožňuje; tečně navazující hrany tvoří jeden přechod se společným poloměrem.": "Each edge can have its own radius; if start and end differ, the radius changes linearly along the edge. Control points in the middle of an edge are not supported by the kernel; tangent-continuous edges form one blend with a common radius.",
