 "Plochy komponenty „{0}“ (souřadnice sestavy, {1}) – rovinné: {2}, válcové/kuželové: {3}{4}": "Faces of component „{0}“ (assembly coordinates, {1}) – planar: {2}, cylindrical/conical: {3}{4}",
