 "Plochy nejsou rovnoběžné – založena půlicí rovina.": "The faces are not parallel – a bisecting plane was created.",
 "Plochy netvoří jednu souvislou skořepinu – nejdřív je sešijte (Sešít plochy) nebo zvětšete toleranci.": "The faces do not form one continuous shell – sew them first (Sew surfaces) or increase the tolerance.",
 "Plochy neuzavírají objem – {0} volných hran (chybí stěna nebo jsou mezery; zvětšete toleranci).": "The faces do not enclose a volume – {0} free edges (a wall is missing or there are gaps; increase the tolerance).",
 "Plochy neuzavírají objem – chybí některá stěna nebo jsou mezery.": "The faces do not enclose a volume – a wall is missing or there are gaps.",
 "Plochy neuzavírají objem – zkontrolujte, že na sebe navazují (Sešít plochy).": "The faces do not enclose a volume – check that they are connected (Sew surfaces).",
 "Plochy podle pravidla „{0}“: {1}": "Faces by rule “{0}”: {1}",
 "Plochy se naklopí o úhel kolem průsečnice s neutrální rovinou; směr tahu určuje, na kterou stranu se úkos otevírá (u zadané roviny jen otočí její orientaci). Bez roviny i směru platí základní rovina. Úkos na obě strany od dělicí čáry a stupňovitý úkos: přepněte Neutrální prvek na Dělicí křivka.": "The faces are tilted by the angle about their intersection with the neutral plane; the pull direction decides which way the draft opens (with a given plane it only flips its orientation). Without plane and direction the base plane applies. Draft to both sides of a parting line and step draft: switch Neutral element to Parting curve.",
 "Plochy se rozdělí dělicí křivkou; části nad ní se zkosí ve směru tahu, části pod ní proti němu – dělicí čára zůstane na místě a díl je v ní nejširší. Skica kolmá na tah = rovinná dělicí křivka (dělicí rovina pro obě strany, přesně). Skica rovnoběžná s tahem (např. v nárysu) = profil dělicí čáry promítnutý podél normály skici: přímé úseky přesně, oblouky a spline po rovinných úsecích (přibližně), svislé skoky = stupně. Stupňovitý úkos zkosí každý úsek od vlastní roviny kolmé na tah a sousední úseky spojí stupňovými plochami.": "The faces are split by the parting curve; the parts above it are drafted in the pull direction, the parts below against it – the parting line stays in place and the part is widest there. Sketch perpendicular to the pull = planar parting curve (parting plane for both sides, exact). Sketch parallel to the pull (e.g. in the front view) = parting-line profile projected along the sketch normal: straight segments exact, arcs and splines in planar segments (approximate), vertical jumps = steps. A step draft drafts each segment from its own plane perpendicular to the pull and joins neighbouring segments with step faces.",
