 "Poloměr opsané": "Circumscribed radius",
 "Poloměr osy": "Centreline radius",
 "Poloměr se mění lineárně od začátku hrany (R1) k jejímu konci (R2). Začátek hrany určuje model – běží-li přechod obráceně, hodnoty prohoďte. Různou vzdálenost na každé ploše (eliptický průřez) má druh „Eliptické / kuželosečkové“.": "The radius changes linearly from the start of the edge (R1) to its end (R2). The model decides where the edge starts – if the transition runs the other way, swap the values. A different distance on each face (elliptical section) is the “Elliptical / conic” type.",
