 "pomocný pohled (POHLED B, metoda šipky): kolmo na šikmou plochu viděnou jako hrana v rodičovském pohledu (skutečný tvar), podél hrany, podle rovinné plochy F… nebo směru; zarovnaně s rodičem, šipka s písmenem": "auxiliary view (VIEW B, reference arrow method): normal to an inclined face seen as an edge in the parent view (true shape), along an edge, by a planar face F… or a direction; aligned with the parent, arrow with a letter",
