 "Proměnné najdete v levém panelu – záložka Proměnné.": "Variables are in the left panel – Variables tab.",
 "Proměnné řídí rozměry modelu. V poli parametru napište název proměnné nebo výraz (např.": "Variables drive the model dimensions. In a parameter field type a variable name or an expression (e.g.",
