 "Ve schránce je jediný bod – čára potřebuje aspoň dva (čísla po dvojicích X Y).": "The clipboard holds a single point – a line needs at least two (numbers in X Y pairs).",
 "Ve SketchUpu: Soubor → Exportovat → 3D model → „OBJ“ nebo „STL“, ty pak otevřete zde.": "In SketchUp: File → Export → 3D Model → “OBJ” or “STL”, then open them here.",
