 "Zatím žádný motor. Rotační motor otáčí komponentou na vazbě Závěs / Souosost / Šroub, lineární ji posouvá na vazbě Vzdálenost / Drážka / Dráha / Souosost.": "No motor yet. A rotary motor turns a component on a Hinge / Concentric / Screw mate, a linear motor moves it on a Distance / Slot / Path / Concentric mate.",
