 "Zleva": "Left",
 "změní geometrii entity jako panel vlastností: klíč hodnota nebo klíč=hodnota (úsečka a b length angle; kružnice c r d area; oblouk c r a0 a1; křivka closed width v1… b1…; elipsa c a b rot t0 t1; text s p h rot style halign valign wf oblique; bod p; přímka p angle)": "changes the entity geometry like the properties panel: key value or key=value (line a b length angle; circle c r d area; arc c r a0 a1; polyline closed width v1… b1…; ellipse c a b rot t0 t1; text s p h rot style halign valign wf oblique; point p; xline p angle)",
 "změní parametry existujícího prvku na místě (prvek = název v uvozovkách, id, $last nebo @3 = 3. prvek historie); klíče jako u příkazu prvek, u rozšíření i popisek; plochy / hrany čísly, E7 / F3 nebo pravidlem nad tělesem před prvkem; „==výraz“ naváže parametr na proměnné, číslo vazbu zruší; bez klíčů vypíše parametry": "changes the parameters of an existing feature in place (feature = name in quotes, id, $last or @3 = 3rd history feature); keys as with the feature command, for extensions also the label; faces / edges by number, E7 / F3 or by rule on the body before the feature; “==expression” binds the parameter to variables, a number removes the binding; without keys it lists the parameters",
 "změní pořadí v historii; skica (použitý prvek) musí zůstat před prvky, které ji používají – jinak ✗ s důvodem": "changes the order in the history; a sketch (used feature) must stay before the features that use it – otherwise ✗ with the reason",
 "změní vlastnosti entit (výběr na začátku: e3 e5 / vše / poslední / výběr; jinak aktuální výběr): hladina, barva, typčáry, tloušťka, měřítkočáry, průhlednost; bez vlastností = výpis": "changes entity properties (selection first: e3 e5 / all / last / selection; otherwise the current selection): layer, color, linetype, lineweight, ltscale, transparency; no properties = listing",
